text:
{
  "viewpoint": {
    "person": "third",
    "character": "佐伯スミ",
    "aliases": [
      "スミ"
    ],
    "pronouns": []
  },
  "narrator": {
    "knows_ja": "スミがその場で見聞きしたこと、手に取った紙に書かれていたこと、他人が口に出した言葉まで。他人の内心や、スミがいない場所の出来事は知らない。"
  },
  "sample": "局の棚は、奥の三段だけが冷たい。スミは宛名のない封筒を三通、指の腹で数えるように出した。差出人の名はどれも同じで、切手は貼られていなかった。焼く日は、まだ決めなくてもいい。そう思ったところで、午後の配達の時間が来た。",
  "banned": [
    {
      "id": "b1",
      "pattern": "運命",
      "message_ja": "出来事を運命に預けると、誰が選んだのかが消えるため。"
    },
    {
      "id": "b2",
      "pattern": "奇跡",
      "message_ja": "偶然を奇跡と呼ぶと、記録と記憶の食い違いという主題が薄まるため。"
    },
    {
      "id": "b3",
      "pattern": "涙が(止まらな|あふれ)",
      "message_ja": "感情を身体の決まり文句で済ませず、手の動きや紙の扱いで書くため。"
    }
  ],
  "notes": "会話は短く、方言は語尾だけに残す。"
}
